SELECT CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, CASE WHEN p.stock_qty >= 335 THEN 'high' WHEN p.stock_qty >= 134 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, COUNT(oi.quantity) AS quantity_count FROM order_items oi INNER JOIN products p ON oi.product_id = p.id INNER JOIN orders o ON o.id = oi.order_id WHERE o.customer_id = 3 GROUP BY CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END, CASE WHEN p.stock_qty >= 335 THEN 'high' WHEN p.stock_qty >= 134 THEN 'mid' ELSE 'low' END ORDER BY stock_qty_bucket, launch_cohort LIMIT 5
